#!/usr/bin/env python3
"""AI-generated by OpenAI Codex, 2026-11-02. Verify bundled benchmark bytes.

This checks integrity only; numerical parsing and solver validation are pending.
"""

import hashlib
import json
from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[1]
MANIFESTS = (
    ROOT / "bees_optimization/data/manifest.json",
    ROOT / "portfolio_optimization/data/manifest.json",
)


def verify_manifest(path: Path) -> int:
    """Check every file in one manifest and return the number checked."""
    manifest = json.loads(path.read_text(encoding="utf-8"))
    for record in manifest["files"]:
        data_path = path.parent / record["path"]
        content = data_path.read_bytes()
        digest = hashlib.sha256(content).hexdigest()
        if len(content) != record["bytes"] or digest != record["sha256"]:
            raise ValueError(f"Dataset integrity mismatch: {data_path.relative_to(ROOT)}")
        print(f"OK {data_path.relative_to(ROOT)}")
    return len(manifest["files"])


def main() -> int:
    """Report a nonzero exit status for missing or changed benchmark files."""
    try:
        count = sum(verify_manifest(path) for path in MANIFESTS)
    except (OSError, ValueError, KeyError, TypeError) as error:
        print(f"Verification failed: {error}", file=sys.stderr)
        return 1
    print(f"Verified {count} original benchmark files. No optimization was run.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
